def transform(grid):
    h, w = len(grid), len(grid[0])
    row_seps = [r for r in range(h) if all(v == 8 for v in grid[r])]
    col_seps = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    row_bands = []
    start = 0
    for s in row_seps:
        if start < s:
            row_bands.append((start, s))
        start = s + 1
    if start < h:
        row_bands.append((start, h))
    col_bands = []
    start = 0
    for s in col_seps:
        if start < s:
            col_bands.append((start, s))
        start = s + 1
    if start < w:
        col_bands.append((start, w))

    markers = {}
    for r in range(h):
        if r in row_seps:
            continue
        tr = sum(s < r for s in row_seps)
        for c in range(w):
            v = grid[r][c]
            if c in col_seps or v in (0, 8):
                continue
            tc = sum(s < c for s in col_seps)
            markers.setdefault(v, []).append((tr, tc))

    paints = {}
    for color, points in markers.items():
        for i, (r1, c1) in enumerate(points):
            for r2, c2 in points[i + 1:]:
                if r1 == r2:
                    for c in range(min(c1, c2), max(c1, c2) + 1):
                        paints.setdefault((r1, c), set()).add(color)
                if c1 == c2:
                    for r in range(min(r1, r2), max(r1, r2) + 1):
                        paints.setdefault((r, c1), set()).add(color)

    out = [row[:] for row in grid]
    for (tr, tc), colors in paints.items():
        color = 1
        for c in colors:
            color *= c
        r0, r1 = row_bands[tr]
        c0, c1 = col_bands[tc]
        for r in range(r0, r1):
            for c in range(c0, c1):
                out[r][c] = color
    return out
